package clusterdata.datatypes;

import java.io.Serializable;

public class TaskEvent implements Serializable {
    public long timestamp;
    public int missingInfo;
    public long jobId;
    public int taskIndex;
    public long machineId;
    public int eventType;
    public String userName;
    public int schedulingClass;
    public int priority;
    public float cpuRequest;
    public float ramRequest;
    public float diskRequest;
    public boolean differentMachineConstraint;

    public TaskEvent() {}

    public TaskEvent(long timestamp, int missingInfo, long jobId, int taskIndex, long machineId, int eventType, String userName, int schedulingClass, int priority, float cpuRequest, float ramRequest, float diskRequest, boolean differentMachineConstraint) {
        this.timestamp = timestamp;
        this.missingInfo = missingInfo;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.machineId = machineId;
        this.eventType = eventType;
        this.userName = userName;
        this.schedulingClass = schedulingClass;
        this.priority = priority;
        this.cpuRequest = cpuRequest;
        this.ramRequest = ramRequest;
        this.diskRequest = diskRequest;
        this.differentMachineConstraint = differentMachineConstraint;
    }

    public static TaskEvent fromString(String line) {
        String[] tokens = line.split(",");
        if (tokens.length < 13) return null;

        try {
            long timestamp = Long.parseLong(tokens[0]);
            int missingInfo = tokens[1].isEmpty() ? 0 : Integer.parseInt(tokens[1]);
            long jobId = Long.parseLong(tokens[2]);
            int taskIndex = Integer.parseInt(tokens[3]);
            long machineId = tokens[4].isEmpty() ? -1 : Long.parseLong(tokens[4]);
            int eventType = Integer.parseInt(tokens[5]);
            String userName = tokens[6];
            int schedulingClass = Integer.parseInt(tokens[7]);
            int priority = Integer.parseInt(tokens[8]);
            float cpuRequest = tokens[9].isEmpty() ? 0.0f : Float.parseFloat(tokens[9]);
            float ramRequest = tokens[10].isEmpty() ? 0.0f : Float.parseFloat(tokens[10]);
            float diskRequest = tokens[11].isEmpty() ? 0.0f : Float.parseFloat(tokens[11]);
            boolean constraint = tokens[12].equals("1");

            return new TaskEvent(timestamp, missingInfo, jobId, taskIndex, machineId, eventType, userName, schedulingClass, priority, cpuRequest, ramRequest, diskRequest, constraint);
        } catch (NumberFormatException e) {
            return null;
        }
    }
}

